void solve(int x) {
    int a = 1, b = -1, c = 2, d = 1;
    int e = (x + 1) / 3;
    if (std::abs(e) < 1)
        if (x % 3 == 0) e = (x > 0) ? (x / 3 + 1) : (x / 3 - 1);
        else e = (x > 0) ? (x / 3 + (x % 3 > 0)) : (x / 3 - (x % -3 < 0));
